contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 amount) public {
        address self = address(this);

        // Force a deterministic state: mint to the test contract, then freeze it
        c.mintToken(self, 1000); if (__ESBMC_reverted()) return;
        c.freezeAccount(self, true); if (__ESBMC_reverted()) return;

        uint256 balanceBefore = c.balanceOf(self); if (__ESBMC_reverted()) return;

        bool reverted;
        c.burn(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted == (amount >= balanceBefore + 1));
    }
}

