pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 amount) internal {
        address self = address(this);
        try c.mintToken(self, 1000) {} catch { return; }
        try c.freezeAccount(self, true) {} catch { return; }
        uint256 balanceBefore;
        try c.balanceOf(self) returns (uint256 __r) { balanceBefore = __r; } catch { return; }
        bool reverted;
        try c.burn(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == (amount >= balanceBefore + 1));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
